import React, { createContext, useState, useEffect, useContext } from 'react';
import authService from '../services/authService';

export const AuthContext = createContext();

export const useAuth = () => {
    const context = useContext(AuthContext);
    if (!context) {
        throw new Error('useAuth must be used within AuthProvider');
    }
    return context;
};

export const AuthProvider = ({ children }) => {
    console.log('[AuthProvider] Initializing');
    const [user, setUser] = useState(null);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        console.log('[AuthProvider] useEffect running');
        const currentUser = authService.getCurrentUser();
        console.log('[AuthProvider] Current user from service:', currentUser);
        setUser(currentUser);
        setLoading(false);
        console.log('[AuthProvider] Initialization complete');
    }, []);

    const login = async (email, password) => {
        console.log('[AuthProvider] login called with email:', email);
        console.log('[AuthProvider] login stack trace:', new Error().stack);

        try {
            console.log('[AuthProvider] Calling authService.login...');
            const response = await authService.login(email, password);
            console.log('[AuthProvider] authService.login response:', response);
            console.log('[AuthProvider] Setting user:', response.user);
            setUser(response.user);
            console.log('[AuthProvider] Login successful');
            return response;
        } catch (error) {
            console.log('[AuthProvider] === ERROR in login ===');
            console.log('[AuthProvider] Error:', error);
            console.log('[AuthProvider] Error message:', error.message);
            console.log('[AuthProvider] Rethrowing error...');
            throw error;
        }
    };

    const register = async (userData) => {
        console.log('[AuthProvider] register called');
        const response = await authService.register(userData);
        setUser(response.user);
        return response;
    };

    const logout = () => {
        console.log('[AuthProvider] logout called');
        authService.logout();
        setUser(null);
        console.log('[AuthProvider] logout complete');
    };

    const updateProfile = async (userData) => {
        const response = await authService.updateProfile(userData);
        setUser(response.user);
        return response;
    };

    const changePassword = async (passwordData) => {
        return await authService.changePassword(passwordData);
    };

    const deleteAccount = async () => {
        await authService.deleteAccount();
        setUser(null);
    };

    const isAuthenticated = !!user;

    return (
        <AuthContext.Provider value={{
            user,
            loading,
            login,
            register,
            logout,
            updateProfile,
            changePassword,
            deleteAccount,
            isAuthenticated
        }}>
            {children}
        </AuthContext.Provider>
    );
};
